create table if not exists public.site_documents (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),
  title text not null,
  summary text not null default '',
  category text not null default 'General',
  content jsonb not null default '[]'::jsonb check (jsonb_typeof(content) = 'array'),
  source_url text,
  sort_order integer not null default 0,
  published boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid references public.app_auth_users(id) on delete set null
);

create table if not exists public.site_document_revisions (
  id bigserial primary key,
  document_id uuid references public.site_documents(id) on delete set null,
  document_slug text not null,
  action text not null check (action in ('created','updated','deleted','published','unpublished')),
  snapshot jsonb not null,
  changed_at timestamptz not null default now(),
  changed_by uuid references public.app_auth_users(id) on delete set null
);

create index if not exists site_documents_public_order_idx on public.site_documents(published, sort_order, title);
create index if not exists site_document_revisions_changed_at_idx on public.site_document_revisions(changed_at desc);

insert into public.site_documents
  (slug, title, summary, category, content, source_url, sort_order, published)
values
  ('rules-and-regulations', 'Rules and Regulations',
   'Official conduct, operation, TeamSpeak, GARC, MOS, NCO, and Discord standards for the 101st Doom Battalion.',
   'General', $rules$[{"type":"paragraph","align":"center","level":0,"runs":[{"text":"Rules and Regulations","size":24,"font":"Alegreya"}]},{"type":"paragraph","align":"center","level":0,"runs":[{"text":"101st Legion, 3rd Regiment, Doom Battalion","size":11,"font":"Courier New"}]},{"type":"divider","align":"left","runs":[]},{"type":"heading2","align":"center","level":0,"runs":[{"text":"***DISCLAIMER***","size":15,"font":"Arial"}]},{"type":"paragraph","align":"center","level":0,"runs":[{"text":"ALL DOCUMENTED RULES AND REGULATIONS UNLESS SPECIFIED IS THE MINIMUM ENFORCEMENT IN THE 101ST DOOM BATTALION. NCOS AND OFFICERS HAVE DISCRETION ON THE ENFORCEMENT OF ALL INFRACTIONS UNLESS A MAXIMUM ENFORCEMENT IS GIVEN.","bold":true,"underline":true,"size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"The 101st Legion, 3rd Regiment, Doom Battalion, upholds and enforces a 3 Strike Disciplinary Action System. Any trooper regardless of Rank, Billet, or Position is held up to the standard of this system. Any Trooper with 3 Disciplinary Action Reports will be discharged from the unit permanently with possible allowance of a 30 day","bold":true,"size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"(1 month) appeal that is submitted to Battalion Staff.","bold":true,"size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"We reserve the right to remove you from our community if you break a rule, or are causing an otherwise unruly scene, or have been found to promote a toxic or hostile environment in our community. If this is the case, a CS+ will speak to you about the occasion of your ban. Battalion Staff has final say on the matter of the ban. Our NCO Corps is liable to see that the removal was within the parameters for use of this policy.","bold":true,"size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"Any disciplinary report filed on any trooper will be recorded and posted within the report itself for review. Fairness will be given to all person(s) involved in any investigation that may come from that report. Witnesses, offending person(s), and any other party involved with the report of a disciplinary infraction will be recorded.","bold":true,"size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"To preserve the integrity of the community and unit as a whole, the rules and regulations can be changed at any time by Battalion Staff for any ample reason. This is a live document any and all changes, adjustments, or renditions will be announced when made. This document is to be upheld at all times unless Platoon Policies override the minimum enforcement. Any platoon policy that overrides this document's minimum procedures is approved by Battalion Staff before the policy is implemented within the platoon. Any platoon policies broken while within any of the platoon's official operations (Main Operations, FTXs, and Joint Operations.) are forfeit to that platoons COC with involvement of their own platoons COC if necessary.","bold":true,"size":11,"font":"Times New Roman"}]},{"type":"divider","align":"left","runs":[]},{"type":"divider","align":"left","runs":[]},{"type":"heading1","align":"left","level":0,"runs":[{"text":"General Rules and Consequences","bold":true,"size":14,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Do not dual-sim, whether it is a GARC related or non-GARC unit, you may only be in one Star Wars Arma 3 simulation unit. ","size":11,"font":"Times New Roman"},{"text":"Appeal N/A","bold":true,"size":11,"font":"Times New Roman"}],"start":1},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Anyone caught will be banned immediately from the unit and discord.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Do not harass or threaten, verbally or otherwise, any other person or unit in our public or private channels. Do not demand anything of a fellow trooper. Harassment is defined as “to create an unpleasant or hostile situation for especially by uninvited and unwelcome verbal or physical conduct” ","size":11,"font":"Times New Roman"},{"text":"Appeal N/A ","bold":true,"size":11,"font":"Times New Roman"}],"start":2},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Investigation will be handed to an SNCO+.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Do not spam in any channel. ","size":11,"font":"Times New Roman"},{"text":"1 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":3},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Troopers will be asked to stop. Failure to follow will result in mute tag/meme detention.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":2,"runs":[{"text":"Discord: Timeout of 24 hours.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":2,"runs":[{"text":"Teamspeak: First offense kicked from TS. Second offense 24 hour ban.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"No pornography or otherwise overly vulgar, racist, anti-semetic, homophobic and any other hateful remarks of any kind. ","size":11,"font":"Times New Roman"},{"text":"3 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":4},{"type":"bullet","align":"left","level":1,"runs":[{"text":"First offense will result in the message being removed or being removed from the server and you will receive a warning.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Second offense if will result in a permanent meme ban or 24 Hour FLOA","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"We reserve the right to remove you from our community if you break a rule, or are causing an otherwise unruly scene, or have been found to promote a toxic or hostile environment in our community. If this is the case, a CS+ will speak to you about the occasion of your ban. ","size":11,"font":"Times New Roman"},{"text":"Appeal N/A","bold":true,"size":11,"font":"Times New Roman"}],"start":5},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Battalion Staff has final say on the matter of the removal. The NCO Corps is liable to see that the removal was within the parameters for use of this policy.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Disagreements are to remain civil, any escalation of hostility between troopers will result in disciplinary actions upon both parties. ","size":11,"font":"Times New Roman"},{"text":"1 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":6},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Any disagreement that is deemed escalated to hostility will be ended by an NCO","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"If both parties fail to descaulate both parties will be given a 24 hour ban","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Excessive public intoxication of any controlled or non-controlled substances is not allowed within our community, troopers who wish to be in an incoherent state must be in a locked channel on the TS and warn anyone who may be streaming/recording. ","size":11,"font":"Times New Roman"},{"text":"1 Month Appeal ","bold":true,"size":11,"font":"Times New Roman"}],"start":7},{"type":"bullet","align":"left","level":1,"runs":[{"text":"24 Hour ban.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"All troopers are allowed and encouraged to take LOAs when they are going to be absent for more than 3 weeks to avoid any administrative issues. LOAs that are 3-6 Months (ELOA) and LOAs that are 6+ Months (ULOA) or when you do not have an idea for when you will return. When an LOA is started, trooper’s TIG is paused until the LOA ends. ","size":11,"font":"Times New Roman"},{"text":"Appeal N/A","bold":true,"size":11,"font":"Times New Roman"}],"start":8},{"type":"bullet","align":"left","level":1,"runs":[{"text":"When taking ELOAs you will be removed from your billet, ULOAs are down to your COC.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Individuals on LOA’s other than SLOA’s shall not attend ops or be on the TS.","size":12,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Individuals found in violation of this rule will be ejected from Operations and booted from TS until their LOA is finished.","size":12,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Individuals found repeatedly abusing/misusing LOA’s will be put on FLOA to serve out their original LOA or a time decided by their CoC.  ","size":12,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Discussion of Politics of any kind regardless of units position may only take place within locked channels on Teamspeak and all parties agree and consent to discuss the topic. ","size":11,"font":"Times New Roman"},{"text":"3 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":9},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Any discussion that does not remain civil is forfeit to General Rules and Regulation #6","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Members found in violation will be spoken to by a NCOIC or higher.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Do not post and/or share any personal information, including but not limited to real names, addresses, social security, and IDs. Anyone posting others' information will be disciplined and any messages pertaining to that information will be deleted to protect the privacy of the other member. If you post any of your own information, it will be deleted and you will be spoken with by a Battalion Member. ","size":11,"font":"Times New Roman"},{"text":"N/A Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":10},{"type":"bullet","align":"left","level":1,"runs":[{"text":"You may share your real name with other members of the unit if you wish but the 101st Doom Battalion is not liable if your name or any other information is released and/or spread without your consent if you choose to share that information with others.","size":11,"font":"Times New Roman"}]},{"type":"divider","align":"left","runs":[]},{"type":"divider","align":"left","runs":[]},{"type":"heading1","align":"left","level":0,"runs":[{"text":"In-Server Rules and Consequences","bold":true,"size":14,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"No discharging weapons and/or throwing grenades on base. ","size":11,"font":"Times New Roman"},{"text":"2 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":11},{"type":"bullet","align":"left","level":1,"runs":[{"text":"First offense, spoken to by an NCO on the server.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Second offense, kicked/removed from server.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Third offense, removed from all GARC Operations for 24 hours. DA Report Filed.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Friendly fire (Blue on Blue/BoB) will not be tolerated unless absolutely accidental. (Vehicles/In-direct Fire primarily.) If you are inside a detachment and friendly fire, you will be removed from said detachment. ","size":11,"font":"Times New Roman"},{"text":"4 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":12},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Troopers caught will receive a 3 month detachment and vehicle ban(Only if BoB Done with Vehicle).","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":2,"runs":[{"text":"In Regards to Vehicles, accidental Blue On Blue can be absolved provided the gunner/Pilot had no way of knowing friendly locations / was acting on good faith","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"CSM+ may approve/call for an asset denial. Rank not billet.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"101st troopers may only use 101st weapons and equipment during Main Operations, with exceptions given by Zeus and Platoon Leadership with good reason such as rp or scenario basis.","size":11,"font":"Times New Roman"}],"start":13},{"type":"bullet","align":"left","level":1,"runs":[{"text":" When attending Fun Operations 101st troopers may only use approved non 101st weapons and equipment ","size":11,"font":"Times New Roman"},{"text":"“","italic":true,"size":11,"font":"Times New Roman"},{"text":"FunOp 1 to 1 Weapon Swaps ","size":11,"font":"Arial","href":"https://docs.google.com/spreadsheets/d/1myNKpUaGmGu_n3op23Nz-o-WSz0k8D62GPt9fMkhek0/edit?usp=sharing"},{"text":"”","italic":true,"size":11,"font":"Times New Roman"},{"text":". Exceptions can be made by Zeus for rp or scenario bases.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"All air frames are under Hammer Qualification & Hammer oversight.","size":10,"font":"Times New Roman"}],"start":14},{"type":"numbered","align":"left","level":0,"runs":[{"text":"IFV Qualification is required for use of armored ground vehicles. ","size":10,"font":"Times New Roman"},{"text":"1 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":14},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Use of vehicles without qualification will result in a NCO asking you to dismount and a disciplinary filed.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":2,"runs":[{"text":"Blacklist from IFV & MBT.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Exceptions are Ground transports (IE: Tempests, Fenics, etc).","size":10,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Do not use weapons, qualifications, or certifications you are not trained for. ","size":11,"font":"Times New Roman"},{"text":"1 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":16},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Failure to follow weapon qualification/certifications will result in a punishment decided by the qualification or certification lead and trainers.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Running two or more certifications without SOP will result in both certification leads/trainers or the NCO deciding a punishment.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Use of unauthorized non-standard / specialized equipment, i.e. Jump packs and personal shields, will result in a 24 hour operation ban.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Dual wielded pistols are for CS+ anyone using them they will have their kit corrected further infractions will result in removal from operations for ","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":2,"runs":[{"text":"24 Hour Operation Ban","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Orbital designator is barred from use unless you're in a company billet and a CSM+.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":2,"runs":[{"text":"72 Hour Operation Ban","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Any trooper found intentionally moving 50+ meters away from friendly forces without good reason/intent will be deemed lone wolfing and be spoken to by an NCO on server or the head Zeus of the operation for reasoning/explanation. ","size":11,"font":"Times New Roman"},{"text":"3 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":17},{"type":"bullet","align":"left","level":1,"runs":[{"text":"24 hour operation ban","bold":true,"size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"GARC may attend official main operations with prior approval from both 101st Platoon CL/CSM and GARC equivalent leadership","size":11,"font":"Times New Roman"}],"start":18},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Non-Garc units are not permitted to join any operations held on 101st servers unless approved by battalion (Fun Operations only)","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Non-Garc may attend fun operations held on private servers, however they must still adhere to unit rules & regulations if our Teamspeak or Discord is used to publish the op.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":2,"runs":[{"text":"If private teamspeak is also used, all attendees are exempt from our rules and regulations.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Respect of the chain of command for any operation regardless of who is the Squad Lead or Team Lead. ","size":11,"font":"Times New Roman"}],"start":19},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"1 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"First offense will be a verbal warning within the operation, if continued disrespect to that operation COC will result in removal from operation and written warning.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Second offense will result in a minimum of a 24 hour FLOA","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"NCO/Officers will enforce the uniform doctrine with equipment checks at any time; before, during or after operations. ","size":11,"font":"Times New Roman"},{"text":"1 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":20},{"type":"bullet","align":"left","level":1,"runs":[{"text":"If uniform does not meet the ","size":11,"font":"Times New Roman"},{"text":"uniform document","size":11,"font":"Times New Roman","href":"https://docs.google.com/spreadsheets/d/1aIf5Pr5G1q12bSdYjDmEotkPOS-BGQTFa-LGm13gdjE/edit?usp=sharing"},{"text":" found within #all-info-you-need within the discord will result in the NCO/Officer correcting your kit to meet regulation and a notice to the rest of the NCO corp if the kit in question was extreme enough to warrant(ie: Illegal items(Bananas), Banned Weapons, etc) repeat offense will result in a 24 hour operation ban","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Soundboards are not to be used within official operation (i.e.. Main Ops, Joint Ops, etc.); During Fun Operations use is to be non disruptive and any trooper can request for you to stop. Use of soundboards for Zeusing operations are permitted. ","size":11,"font":"Times New Roman"},{"text":"3 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":21},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Failure to stop will result in removal from operation and/or speaking with a NCO on server/TeamSpeak.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Repeat offense is an Operation/server ban of at least 1 day (24 Hours).","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Medical conditions (ie: mute) may use a soundboard within all operations for communication purposes only.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"When respawning in operations you must reload your kit to be at full capacity with ammunitions, medical etc. You must also reload kits if you have acquired an asset from field requisition or have made a drastic change to your kit in-field","size":11,"font":"Times New Roman"},{"text":". If a change in kit is needed during an operation you must have leadership approval. ","size":12,"font":"Times New Roman"},{"text":"1 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":22},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Fun operations require Squad lead approval to change kits. Main operations require Squad lead approval to change kits.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Streaming any training must have the permission of the test proctor and relevant lead. SNCO/Officers are allowed to record for Company/Battalion review. ","size":12,"font":"Times New Roman"},{"text":"3 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":23},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Anyone found streaming during a training without permission will be removed from the server.","size":12,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Anyone found streaming any exams will be forfeit to that Platoon’s SNCO or Officer.","size":12,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Do not use any form of in-game bugs or glitches of any kind. If a trooper is found intentionally using an in-game bug or glitch and an NCO/Officer deems it exploiting the trooper will be requested to leave the server and a report will be filed. This includes but is not limited to: Infinite deployable ammo glitch, ragdolling through walls, and debug ramming with vehicles. ","size":11,"font":"Times New Roman"},{"text":"2 Month Appeal.","bold":true,"size":11,"font":"Times New Roman"}],"start":24},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Troopers who are found to be unintentionally using an exploit will be told to stop with explanation of the exploit in question.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":2,"runs":[{"text":"24 Hour Operation Ban","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"While inside any vehicle respect its crew and their directions. This includes but is not limited to; Excessive non-essential talking, Removing items from the inventory, user controlled actions(LAAT Ramp). ","size":11,"font":"Times New Roman"},{"text":" ","size":12,"font":"Times New Roman"},{"text":"1 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":25},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Troopers found not respecting nor listening to its crew or an NCO when instructed to stop will be removed from the vehicle.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Repeat offenders' punishments are at the crew's discretion, punishments include but are not limited to being disallowed from using that vehicle in any capacity including riding as a passenger.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"While running on 101st Servers you are not permitted to use any of the ","size":11,"font":"Times New Roman"},{"text":"Blacklisted Mods","size":11,"font":"Times New Roman","href":"https://docs.google.com/document/d/1MMbaNX4jfbU2OPdUgMEqs0z0PmvJ2gJPae4xeayp7k8/edit?usp=sharing"},{"text":". ","size":11,"font":"Times New Roman"},{"text":"3 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":26},{"type":"bullet","align":"left","level":1,"runs":[{"text":"All mods that allow similar mechanics are also blacklisted. (Exception for Pre Approved Mods)","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Troopers found utilizing a blacklisted mod may be asked to leave the operation and unload the blacklisted mods.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Troopers found repeatedly utilizing blacklisted mods will result in a 24 Hour Operation ban. Disciplinary filed.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"While running on 101st Servers you must abide by these Chat Guidelines. The use of any of these chats to transmit any information regarding an operation is forbidden. Ex. Bulldogging in Group Chat or calling out AAT in Side Chat. ","size":11,"font":"Times New Roman"},{"text":"1 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":27},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"- Direct Communication: Can be used for peer to peer communication in an out of character fashion. Also can be used for communication for someone without a microphone. PTS applies to this chat when in effect.","size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"- Global Channel: Used for emergency contact with Zeus if LR is not available. ","size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"- Side Channel: Can be used as a replacement for Ground to Ground for members who do not have a microphone (LR Etiquette still applies). Also used to notify Hammer of reinserts when the kill notification is disabled. When needed only say “#x Reinsert(s)” and do not hound Hammer.","size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"- Command Channel: Can be used for communication between squad leaders in an out of character fashion. No practical use.","size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"- Group Channel: Can be used for communication between members in a squad in an out of character fashion. May notify when a member is unconscious by typing \"Down\" or \"Uncon\"","size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"- Vehicle Channel: Can be used for communication in a vehicle in an out of character fashion. Vehicle crew has final say in policing this chat in operations. Also can be used to notify medics if a member requires medical attention.","size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"25.1. Troopers found consistently using the In-Game chat incorrectly will be given a verbal or written warning.","size":11,"font":"Times New Roman"}]},{"type":"heading1","align":"left","level":0,"runs":[{"text":"Teamspeak Rules and Consequences","bold":true,"size":14,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Any GARC Member within the TeamSpeak may go below the TFAR Channel so long as they are in a locked channel, with a CSM+ for a meeting, or for any specialized training. All Retired members are allowed past the TFAR channel. Unit Guests & Non GARC are allowed within Fraternization channels and Locked Offices. ","size":12,"font":"Times New Roman"},{"text":"1 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":28},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Failure to abide by will result in the person(s) being moved to a longue/gaming channel, repeated action will result in a 24 hour ban from TS.","size":12,"font":"Times New Roman"}]},{"type":"divider","align":"left","runs":[]},{"type":"heading1","align":"left","level":0,"runs":[{"text":"GARC Server Rules and Regulations","bold":true,"size":14,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"When visiting other servers, you are a guest on their server and must follow the rules set forth by that GARC community. ","size":11,"font":"Times New Roman"},{"text":"3 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":29},{"type":"bullet","align":"left","level":1,"runs":[{"text":"While on another GARC community’s server, you have agreed to abide by the rules they have set. It is ","size":11,"font":"Times New Roman"},{"text":"your","italic":true,"size":11,"font":"Times New Roman"},{"text":" responsibility to read and know what those rules are.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"When going over to another GARC Server, CR-Cs are required to have a CST+ escort. ","size":11,"font":"Times New Roman"},{"text":"3 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":30},{"type":"bullet","align":"left","level":1,"runs":[{"text":"If your escort disconnects due to technical difficulties, you are able to continue the operation as normal until they return.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"If your escort must leave and disconnect and another person cannot fulfill the CST+ escort, continue until the finish of that current OBJ then disconnect.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"If you ever have a question about what you can/cannot run on other GARC servers, ask a zeus or GARC NCO who is present during the operation for clarification and/or permission. ","size":11,"font":"Times New Roman"},{"text":"Appeal N/A","bold":true,"size":11,"font":"Times New Roman"}],"start":31},{"type":"numbered","align":"left","level":0,"runs":[{"text":"While visiting other communities, you will still be held accountable to the rules and regulations established in this document. ","size":11,"font":"Times New Roman"},{"text":"3 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":32},{"type":"numbered","align":"left","level":0,"runs":[{"text":"While visiting other servers, you are an ambassador acting on behalf of the 101st and are expected to compose yourself as such. Incidents on other GARC servers may be dealt with more severely by NCO/Officers. ","size":11,"font":"Times New Roman"},{"text":"6 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":33},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Any visiting GARC units detachments/MOS without existing agreements (ie; Airborne, Flight, RTO's and Medics already have agreements) may not detach or receive special perms from Zeus until Battalion and/or the appropriate detachment lead has approved their SOP. ","size":11,"font":"Times New Roman"},{"text":"N/A Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":34},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Any unapproved detachments/MOS will fall into and run with GI until a ruling is made.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Currently approved detachments: 327th, 91st and 212th ","size":11,"font":"Times New Roman"},{"text":"ARF","size":11,"font":"Times New Roman","href":"https://docs.google.com/document/d/1xcl5dPGSSqpJ3Fy94BtfNEezEmuI44P7am1jBfztMC0/edit?usp=sharing"},{"text":". 501st and 212th Airborne, 212th only within joint operations. 91st ARC may run within all operations. All medical MOS. 501st, 91st, 327th and 91st Radio MOS.","size":11,"font":"Times New Roman"}]},{"type":"heading1","align":"left","level":0,"runs":[{"text":"Aviation Standards and Regulations","bold":true,"size":14,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"GARC Aviation","size":11,"font":"Times New Roman"}],"start":35},{"type":"bullet","align":"left","level":1,"runs":[{"text":"GARC members are not to fly unless higher or of the rank of CX (Flight Ensign) any failure on this part is to be sent to Hammer HQ for discussion with GARC aviation COC.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"GARC members may not fly aircraft that 101st members are not allowed to fly, any failure to abide by these rules is to be sent to Hammer HQ for discussion with GARC aviation COC.","size":11,"font":"Times New Roman"}]},{"type":"divider","align":"left","runs":[]},{"type":"heading1","align":"left","level":0,"runs":[{"text":"ARF Standards and Regulations","bold":true,"size":14,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Non-ARF troopers can not wear ARF uniform or use ARF only equipment ","size":11,"font":"Times New Roman"},{"text":"1 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":36},{"type":"bullet","align":"left","level":1,"runs":[{"text":"If a trooper is using ARF equipment, they will be given a disciplinary following the three strike policy","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Troopers cannot use ARF uniforms (camo, base) in Ops. During role play operations troopers may ask Longbow HQ for permission to roleplay as 101st ARF","size":11,"font":"Times New Roman"}]},{"type":"divider","align":"left","runs":[]},{"type":"heading1","align":"left","level":0,"runs":[{"text":"Dagger Standards and Regulations","bold":true,"size":14,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"The jump pack is to be used as a tool, not a toy. Any trooper seen misusing the jump pack should be reported to a Dagger NCO to be dealt with. Anyone misusing the Jump Pack will be given a Written Warning, continued misuse will result in Losing Colors or removal from dagger ","size":11,"font":"Times New Roman"},{"text":"1 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":37},{"type":"numbered","align":"left","level":0,"runs":[{"text":"All Dagger Troopers (Ride Alongs included) are to follow the rules and regulations found withinside the ","size":11,"font":"Times New Roman"},{"text":"Dagger Detachment SOP","size":11,"font":"Times New Roman","href":"https://docs.google.com/document/d/1VM7o4lmc-ZaV-M0VoS3Uz9fjzn8T7gahkAdmA01RfLc/edit?usp=sharing"},{"text":" ","size":11,"font":"Times New Roman"},{"text":"1 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":38},{"type":"numbered","align":"left","level":0,"runs":[{"text":"When Attending a GARC Operation, Dagger are to follow the Airborne ","size":11,"font":"Times New Roman"},{"text":"Detachment Rules","size":11,"font":"Times New Roman","href":"https://docs.google.com/document/d/1VM7o4lmc-ZaV-M0VoS3Uz9fjzn8T7gahkAdmA01RfLc/edit#bookmark=id.24h06w3czs1r"},{"text":", or ","size":11,"font":"Times New Roman"},{"text":"Non Detached Rules","size":11,"font":"Times New Roman","href":"https://docs.google.com/document/d/1VM7o4lmc-ZaV-M0VoS3Uz9fjzn8T7gahkAdmA01RfLc/edit#bookmark=id.rj5x20ug3xy4"},{"text":" ","size":11,"font":"Times New Roman"},{"text":"3 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":39},{"type":"numbered","align":"left","level":0,"runs":[{"text":"When Attending a GARC Operation, Dagger are to follow the GARC Units Airborne Jump Codes, found within the ","size":11,"font":"Times New Roman"},{"text":"GARC Airborne Rules","size":11,"font":"Times New Roman","href":"https://docs.google.com/document/d/1_1kxpxNMRjbKDk__mC7mxF-VKJVsTDQN0pftoUZ28O4/edit?usp=sharing"},{"text":" ","size":11,"font":"Times New Roman"},{"text":"3 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":40},{"type":"divider","align":"left","runs":[]},{"type":"heading1","align":"left","level":0,"runs":[{"text":"Gladius Standards and Regulations","bold":true,"size":14,"font":"Times New Roman"}]},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"When acting as an ARC trooper following troopers should follow the guidelines within the","size":11,"font":"Times New Roman"},{"text":" Gladius Document","size":11,"font":"Times New Roman","href":"https://docs.google.com/document/d/1Ndw1X1QxIAGInZ2XaDZLYvTQc5aNucZKJXs6dqolEDI/edit?usp=sharing"},{"text":".","size":11,"font":"Times New Roman"}]},{"type":"heading1","align":"left","level":0,"runs":[{"text":"Medical Standards and Regulations","bold":true,"size":14,"font":"Times New Roman"}]},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"Medical command reserves the right to make changes to this section at all times with no notification of changes. All cases can also be judged on a case-by-case basis.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Any trooper acting as medical personnel (I.E. CLS, CM or otherwise) must maintain proper kit and decorum. ","size":11,"font":"Times New Roman"},{"text":"3 month appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":41},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Any trooper running a medical kit is subject to a kit-check by a CM or higher rank as needed. Refusal to submit to a kit check is grounds for disciplinary action including but not limited to demotion of MOS rank or removal from program.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Misuse or abuse of medications and equipment (AEDs, tourniquets, etc.).","size":11,"font":"Times New Roman"},{"text":" 3 month appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":42},{"type":"bullet","align":"left","level":1,"runs":[{"text":"“Morphine-Bombing” is the act of applying an excessive amount of drugs into an entity. Morphine-bombing, outside of direct order from platoon or higher members, is grounds for immediate removal from the MOS, and further disciplinary action.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"“Misuse of Equipment”, is the usage of medical equipment outside of their intended use. ","size":11,"font":"Times New Roman"}]},{"type":"divider","align":"left","runs":[]},{"type":"heading1","align":"left","level":0,"runs":[{"text":"Radio Telephone Operator (RTO) Standards and Regulations","bold":true,"size":14,"font":"Times New Roman"}]},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"Failure to follow the rules regarding this section will be handled in a case by case fashion by the relevant CI-P or higher. Reservists are forfeit to CI-S or higher.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"While a trooper is speaking on the long range radio (LR), they are to be respectful and professional at all times. Any arguing, insulting or any other unprofessional behavior will not be tolerated at any time on the LR. ","size":11,"font":"Times New Roman"},{"text":"3 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":43},{"type":"bullet","align":"left","level":1,"runs":[{"text":"NCO Intercommunicors will speak with the offending person(s) about their infraction on long range. Person(s) will receive a written warning after being spoken with by a CI-P or higher.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Non-MOS NCOs will not speak with any offending person unless a CI-P or higher is present.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Map markers should be professional and not contain any vulgar slang and/or terms within the name. ","size":11,"font":"Times New Roman"},{"text":"1 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":44},{"type":"bullet","align":"left","level":1,"runs":[{"text":"NCO will speak with the offending person(s) about their infraction on map. Person(s) will receive a written warning after being spoken with by a CI-P or higher.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Non-MOS NCOs will not speak with any offending person unless a CI-P or higher is present.","size":11,"font":"Times New Roman"}]},{"type":"divider","align":"left","runs":[]},{"type":"heading1","align":"left","level":0,"runs":[{"text":"Officer/NCO Standards and Regulations","bold":true,"size":14,"font":"Times New Roman"}]},{"type":"paragraph","align":"left","level":0,"runs":[{"text":"The Officers and NCOs of the 101st are here to maintain our community and guide our members with any issues or queries they have. Officers and NCOs are role models and help maintain control both in and out of the server. Officers and NCOs do this through Disciplinary Warnings and Action reports.","size":11,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"ALL Officers and NCOs are subject to the rules written within this document and, as such, subject to the consequences accompanying those rules. ","size":11,"font":"Times New Roman"},{"text":"Appeal N/A","bold":true,"size":11,"font":"Times New Roman"}],"start":45},{"type":"numbered","align":"left","level":0,"runs":[{"text":"If it is found that an NCO or Officer is misbehaving or abusing their position, you can report these issues to their superior ","size":11,"font":"Times New Roman"},{"text":"6 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":46},{"type":"numbered","align":"left","level":0,"runs":[{"text":"NCOs and Officers do not hold a guaranteed rank. They are still eligible to receive demotions and be expelled from their respective programs. Officers and NCOs found exhibiting repeat behavior unbefitting of an NCO or Officer may be removed from their Billet and/ or receive a Disciplinary action and/ or be Banned from future NCO positions. ","size":11,"font":"Times New Roman"},{"text":"Appeal N/A","bold":true,"size":11,"font":"Times New Roman"}],"start":47},{"type":"numbered","align":"left","level":0,"runs":[{"text":"NCOs and Officers are not guaranteed level moderators. Abuse of level moderator will have it removed or dropped to a lower level of moderator. ","size":11,"font":"Times New Roman"},{"text":"3 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":48},{"type":"numbered","align":"left","level":0,"runs":[{"text":"NCOs are required to report disciplinary infractions to that trooper(s) NCOIC while filing a disciplinary action. NCOs are required to file a disciplinary infarction when they witness it.","size":11,"font":"Times New Roman"},{"text":" ","size":11,"font":"Arial"},{"text":"1 Month Appeal","bold":true,"size":11,"font":"Times New Roman"}],"start":49},{"type":"bullet","align":"left","level":1,"runs":[{"text":"All Reservists fall under the Battalion SNCO or their 2ic when on LOA.","size":11,"font":"Times New Roman"}]},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Any and all NCOs that do not or participate in an infraction not being filed in some way, shape, or form will lose their rank.","size":11,"font":"Times New Roman"}]},{"type":"heading1","align":"left","level":0,"runs":[{"text":"Discord Rules","bold":true,"size":14,"font":"Times New Roman"}]},{"type":"numbered","align":"left","level":0,"runs":[{"text":"Thou Shalt always consult pinned messages!!!!","size":11,"font":"Times New Roman"}],"start":50},{"type":"bullet","align":"left","level":1,"runs":[{"text":"Failure to do so will result in ridicule from your peers","size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"right","level":0,"runs":[{"text":"Signed, ","size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"right","level":0,"runs":[{"text":"CX-O 72149 “Akhari”","size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"right","level":0,"runs":[{"text":"Clone Ensign Overseer. Doom Battalion","size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"right","level":0,"runs":[{"text":"Battalion CX-O","size":11,"font":"Times New Roman"}]},{"type":"paragraph","align":"right","level":0,"runs":[{"text":"101st Legion ","size":8,"font":"Courier New"}]},{"type":"paragraph","align":"right","level":0,"runs":[{"text":"Grand Army of the Republic ","size":8,"font":"Courier New"}]},{"type":"paragraph","align":"right","level":0,"runs":[{"text":"P","italic":true,"size":14,"font":"Oswald"}]}]$rules$::jsonb,
   'https://docs.google.com/document/d/15tsyHzBSaqfvB-VcIr-eGbhROFKbX8zjc3_L4fA2ZrQ/edit?usp=sharing', 0, true)
on conflict (slug) do nothing;

alter table public.site_documents enable row level security;
alter table public.site_document_revisions enable row level security;
revoke all on public.site_documents from public;
revoke all on public.site_document_revisions from public;
grant select, insert, update, delete on public.site_documents to roster_app_runtime;
grant select, insert on public.site_document_revisions to roster_app_runtime;
grant usage, select on sequence public.site_document_revisions_id_seq to roster_app_runtime;

drop policy if exists "native runtime site documents" on public.site_documents;
create policy "native runtime site documents" on public.site_documents for all to roster_app_runtime using (true) with check (true);
drop policy if exists "native runtime site document revisions" on public.site_document_revisions;
create policy "native runtime site document revisions" on public.site_document_revisions for all to roster_app_runtime using (true) with check (true);

insert into public.app_page_permissions (permission_key, page_path, label, category, description)
values ('admin.documents', '/admin/documents', 'Document Library', 'Systems',
        'Review and maintain published website documents and rich-text content.')
on conflict (permission_key) do update
set page_path=excluded.page_path, label=excluded.label, category=excluded.category,
    description=excluded.description, updated_at=now();

insert into public.user_page_permissions (user_id, permission_key, access_level, granted_by, updated_at)
select users.id, 'admin.documents', 'full', users.id, now()
from public.app_auth_users users
where lower(users.username) = 'akhari'
on conflict (user_id, permission_key) do update
set access_level='full', granted_by=excluded.granted_by, updated_at=now();
